1	/*
2	 * Andes ACE helper functions
3	 *
4	 * Copyright (c) 2023 Andes Technology Corp.
5	 * SPDX-License-Identifier: GPL-2.0-or-later
6	 */
7	#include "andes_ace_helper.h"
8	#include <stdio.h>
9	#include <string.h>
10	#include <dlfcn.h>
11	
12	AceAgentFuncPtr ace_agent_cb_func_table[] = {
13	    (AceAgentFuncPtr)qemu_get_XRF, (AceAgentFuncPtr)qemu_set_XRF,
14	    (AceAgentFuncPtr)qemu_get_FRF, (AceAgentFuncPtr)qemu_set_FRF,
15	    (AceAgentFuncPtr)qemu_get_VRF, (AceAgentFuncPtr)qemu_set_VRF,
16	    (AceAgentFuncPtr)qemu_get_MEM, (AceAgentFuncPtr)qemu_set_MEM,
17	    (AceAgentFuncPtr)qemu_get_CSR, (AceAgentFuncPtr)qemu_set_CSR,
18	    (AceAgentFuncPtr)qemu_set_CSR_masked,
19	    (AceAgentFuncPtr)qemu_get_ACM, (AceAgentFuncPtr)qemu_set_ACM,
20	    (AceAgentFuncPtr)qemu_get_PC,
21	    (AceAgentFuncPtr)qemu_get_hart_id,
22	    (AceAgentFuncPtr)qemu_get_cpu_priv,
23	    (AceAgentFuncPtr)qemu_get_ACES, (AceAgentFuncPtr)qemu_set_ACES,
24	    (AceAgentFuncPtr)qemu_ace_add_reg_desc,
25	    };
26	
27	/* QEMU ACE agent handler */
28	void *qemu_ace_agent_handle;
29	
30	int32_t qemu_ace_agent_load(const char *filename)
31	{
32	    /* Check whether handler already loaded? */
33	    if (qemu_ace_agent_handle != NULL) {
34	        return 0;
35	    }
36	    qemu_ace_agent_handle = dlopen(filename, RTLD_NOW | RTLD_LOCAL);
37	    if (!qemu_ace_agent_handle) {
38	        return -1;
39	    }
40	    return 0;
41	}
42	
43	int32_t qemu_ace_agent_load_symbol(const char *symbol_name, void **func_ptr)
44	{
45	    if (qemu_ace_agent_handle == NULL) {
46	            return -1;
47	    }
48	    /* Clear any existing error */
49	    dlerror();
50	    *(void **)(func_ptr) = dlsym(qemu_ace_agent_handle, symbol_name);
51	    if (*func_ptr == NULL) {
52	        return -1;
53	    }
54	    return 0;
55	}
56	
57	int32_t qemu_ace_agent_register(CPURISCVState *env, const char *extlibpath,
58	                                int32_t multi)
59	{
60	    AceAgentVersion ace_agent_version;
61	    target_ulong hartid;
62	#ifndef CONFIG_USER_ONLY
63	    hartid = env->mhartid;
64	#else
65	    hartid = 0;
66	#endif
67	    if (qemu_ace_agent_load_symbol("ace_agent_version",
68	        (void **)&ace_agent_version) != 0) {
69	        return -1;
70	    }
71	    /*
