327	uint64_t qemu_get_CSR(CPURISCVState *env, uint32_t index, uint64_t mask)
328	{
329	    target_ulong value;
330	    riscv_csr_operations ops;
331	    riscv_get_csr_ops(index , &ops);
332	    if (ops.op) {
333	        ops.op(env, index, &value, 0, 0);
334	        return value & mask;
335	    } else if (ops.read != NULL) {
336	        ops.read(env, index, &value);
337	        return value & mask;
338	    }
339	    return 0;
340	}
