342	void qemu_set_CSR(CPURISCVState *env, uint32_t index,
343	                  uint64_t mask, uint64_t value)
344	{
345	    riscv_csr_operations ops;
346	    riscv_get_csr_ops(index , &ops);
347	    if (ops.op) {
348	        ops.op(env, index, NULL, value, mask);
349	    } else if (ops.read != NULL && ops.write != NULL) {
350	        target_ulong old;
351	        ops.read(env, index, &old);
352	        target_ulong new = (value  << CTZLL(mask) & mask) | (old & ~mask);
353	        ops.write(env, index, new);
354	    }
355	}
