463	                           uint32_t GroupIdx, uint32_t NumOfEntry,
464	                           uint32_t EntryWidth, int TypeIn)
465	{
466	    AceAcrInfo *s;
467	    /* ACE simulator should add reg description by group ordering */
468	    if (GroupIdx != env->ace_acracm_reg_number) {
469	        qemu_printf("ACE add reg description failed for group idx = %d\n",
470	                    GroupIdx);
471	        return;
472	    }
473	    env->ace_acr_info_list = g_realloc(env->ace_acr_info_list,
474	        (env->ace_acracm_reg_number + 1) * sizeof(AceAcrInfo));
475	    if (env->ace_acr_info_list == NULL) {
476	        qemu_printf("ACE add reg description failed since realloc memory\n");
477	        return;
478	    }
479	    AceAcrInfo *acr_info_list = env->ace_acr_info_list;
480	    s = &acr_info_list[env->ace_acracm_reg_number];
481	    memset(s, 0, sizeof(AceAcrInfo));
482	    s->width = EntryWidth;
483	    s->num = NumOfEntry;
484	    s->idx = GroupIdx;
485	    strncpy(s->name, GroupName, sizeof(s->name) - 1);
486	    env->ace_acracm_reg_number++;
487	}
