    return env->ace_agent_get_register(env, hartid, g, i, value_len);
}

void qemu_ace_agent_set_register(CPURISCVState *env, uint32_t g,
                                    uint32_t i, const uint64_t *value,
                                    uint32_t value_len)
{
    target_ulong hartid;
